/**
 * Shared test helpers for .json.test.ts files (Plan 32-02).
 *
 * Captures stdout/stderr around a command invocation so envelope-shape
 * assertions can be made deterministically. Used by all 6 query commands'
 * .json.test.ts files (search/context/show/list/related/stats).
 *
 * Per Codex MEDIUM-3: no shell-specific assumptions; pure JS.
 */

import { join } from "node:path";
import { setImmediate, setTimeout } from "node:timers/promises";
import { createOwnedTestDirectory, type OwnedTestDirectory } from "./owned-test-directory.js";

export interface CapturedStreams {
  stdout: string;
  stderr: string;
  exitCode?: number;
}

/**
 * Capture stdout and stderr emitted by `fn` while it runs.
 *
 * Monkey-patches `console.log` and `console.error` for the duration
 * of `fn`, then restores them. Returns concatenated output and the
 * function's `exitCode` (if returned).
 *
 * Single-line outputs are concatenated with newlines.
 */
export async function captureStreams<R extends { exitCode?: number } | undefined>(
  fn: () => Promise<R>
): Promise<CapturedStreams> {
  const stdoutChunks: string[] = [];
  const stderrChunks: string[] = [];
  const log = console.log;
  const err = console.error;
  console.log = (...args: unknown[]) =>
    stdoutChunks.push(args.map((a) => (typeof a === "string" ? a : String(a))).join(" "));
  console.error = (...args: unknown[]) =>
    stderrChunks.push(args.map((a) => (typeof a === "string" ? a : String(a))).join(" "));
  try {
    const result = await fn();
    const out: CapturedStreams = {
      stdout: stdoutChunks.join("\n"),
      stderr: stderrChunks.join("\n"),
    };
    if (result?.exitCode !== undefined) out.exitCode = result.exitCode;
    return out;
  } finally {
    console.log = log;
    console.error = err;
  }
}

/** Owns each database's container without creating the database itself.
 * Cleanup accepts no paths and retains failed capabilities for a later retry.
 * The allocator seam is for local fault injection, never command input.
 */
export function createTempDatabaseTracker(
  allocate: (prefix: string) => OwnedTestDirectory = createOwnedTestDirectory,
) {
  const owned = new Set<OwnedTestDirectory>();
  return {
    makePath(command: string): string {
      const storage = allocate(`memory-json-${command}-`);
      owned.add(storage);
      return join(storage.dir, "memory.db");
    },
    async cleanup(): Promise<void> {
      const pending = [...owned];
      if (pending.length === 0) return;
      // Closed native SQLite statements can remain alive until GC and a turn.
      Bun.gc(true);
      await setImmediate();
      const failures: Error[] = [];
      for (const storage of pending) {
        let retries = 0;
        while (true) {
          try {
            storage.cleanup();
            owned.delete(storage);
            break;
          } catch (cause) {
            const removalCause = cause instanceof Error ? cause.cause : undefined;
            const busy = removalCause instanceof Error && "code" in removalCause &&
              (removalCause.code === "EBUSY" || removalCause.code === "EPERM");
            if (busy && retries < 2) {
              await setTimeout(++retries * 100);
              Bun.gc(true);
              await setImmediate();
              continue; // Each attempt revalidates the owned-directory capability.
            }
            failures.push(new Error(`JSON test storage retained: ${storage.dir}`, { cause }));
            break;
          }
        }
      }
      if (failures.length > 0) {
        throw new AggregateError(failures, failures.map(error => error.message).join("\n"));
      }
    }
  };
}

import { describe, expect, it } from "bun:test";
import { existsSync, mkdirSync, readFileSync, renameSync, rmdirSync, rmSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { captureStreams, createTempDatabaseTracker } from "./capture-json.js";
import { createOwnedTestDirectory } from "./owned-test-directory.js";

describe("capture-json test helpers", () => {
  it("captures both streams, non-string arguments, and returned exit code", async () => {
    const captured = await captureStreams(async () => {
      console.log("status", 200, { ok: true });
      console.error("warning", false);
      return { exitCode: 7 };
    });
    expect(captured).toEqual({ stdout: "status 200 [object Object]", stderr: "warning false", exitCode: 7 });
  });

  it("omits absent exitCode and preserves a successful zero exit code", async () => {
    const absent = await captureStreams(async () => undefined);
    const empty = await captureStreams(async () => ({}));
    expect(absent).toStrictEqual({ stdout: "", stderr: "" });
    expect(empty).toStrictEqual({ stdout: "", stderr: "" });
    expect("exitCode" in absent).toBe(false);
    expect("exitCode" in empty).toBe(false);
    expect(await captureStreams(async () => ({ exitCode: 0 }))).toStrictEqual({ stdout: "", stderr: "", exitCode: 0 });
  });

  it("restores console methods and preserves a command failure", async () => {
    const log = console.log, error = console.error, failure = new Error("boom");
    await expect(captureStreams(async () => {
      console.log("before throw");
      throw failure;
    })).rejects.toBe(failure);
    expect(console.log).toBe(log);
    expect(console.error).toBe(error);
  });

  it("allocates an absent database in an owned directory and removes its sidecars", async () => {
    const tracker = createTempDatabaseTracker();
    const db = tracker.makePath("helper");
    try {
      expect(existsSync(db)).toBe(false);
      expect(existsSync(dirname(db))).toBe(true);
      for (const suffix of ["", "-wal", "-shm"]) writeFileSync(db + suffix, "synthetic");
      await tracker.cleanup();
      expect(existsSync(dirname(db))).toBe(false);
      await tracker.cleanup();
    } finally { await tracker.cleanup(); }
  });

  it("cannot acquire deletion authority from caller-provided foreign paths", async () => {
    const foreign = createOwnedTestDirectory("memory-json-foreign-");
    const sentinel = join(foreign.dir, "foreign.db");
    writeFileSync(sentinel, "synthetic foreign data");
    const tracker = createTempDatabaseTracker();
    try {
      // JavaScript callers may supply extra arguments; none are deletion inputs.
      await Reflect.apply(tracker.cleanup, tracker, [[sentinel]]);
      expect(readFileSync(sentinel, "utf8")).toBe("synthetic foreign data");
      expect(() => tracker.makePath(sentinel)).toThrow("Invalid test directory prefix");
    } finally { foreign.cleanup(); }
  });

  it("rejects separators and oversized labels before allocating storage", () => {
    const tracker = createTempDatabaseTracker();
    for (const label of ["../escape", "..\\escape", "a".repeat(80)]) {
      expect(() => tracker.makePath(label)).toThrow("Invalid test directory prefix");
    }
  });

  it("preserves allocation failures", async () => {
    const failure = new Error("allocation unavailable");
    const tracker = createTempDatabaseTracker(() => { throw failure; });
    expect(() => tracker.makePath("helper")).toThrow(failure);
    await tracker.cleanup();
  });

  it("refuses a replaced directory and retains authority for a safe retry", async () => {
    const original = createOwnedTestDirectory("memory-json-replaced-");
    const tracker = createTempDatabaseTracker(() => original);
    const db = tracker.makePath("helper");
    const saved = original.dir + "-original";
    renameSync(original.dir, saved);
    mkdirSync(original.dir);
    const sentinel = join(original.dir, "foreign.txt");
    writeFileSync(sentinel, "replacement must survive");
    try {
      await expect(tracker.cleanup()).rejects.toThrow(original.dir);
      expect(readFileSync(sentinel, "utf8")).toBe("replacement must survive");
      expect(existsSync(saved)).toBe(true);
    } finally {
      // Only the exact synthetic sentinel and now-empty replacement are removed.
      unlinkSync(sentinel);
      rmdirSync(original.dir);
      renameSync(saved, original.dir);
      await tracker.cleanup();
    }
    expect(existsSync(dirname(db))).toBe(false);
  });

  it("retains multiple failures and causes while cleaning independent fixtures", async () => {
    let locked = true;
    const failures = [new Error("busy-one"), new Error("busy-two")];
    const storage = failures.map(failure => createOwnedTestDirectory("memory-json-busy-", {
      remove(path) {
        if (locked) throw failure;
        rmSync(path, { recursive: true, force: false });
      },
    }));
    const healthy = createOwnedTestDirectory("memory-json-healthy-");
    const queue = [...storage, healthy];
    const tracker = createTempDatabaseTracker(() => queue.shift()!);
    for (let n = 0; n < 3; n++) tracker.makePath("helper");
    try {
      let result: unknown;
      try { await tracker.cleanup(); } catch (error) { result = error; }
      expect(result).toBeInstanceOf(AggregateError);
      const aggregate = result as AggregateError;
      expect(aggregate.errors).toHaveLength(2);
      for (const [index, item] of storage.entries()) {
        expect(aggregate.message).toContain(item.dir);
        expect(aggregate.errors[index].cause.cause).toBe(failures[index]);
        expect(existsSync(item.dir)).toBe(true);
      }
      expect(existsSync(healthy.dir)).toBe(false);
      locked = false;
      await tracker.cleanup();
      for (const item of storage) expect(existsSync(item.dir)).toBe(false);
    } finally {
      locked = false;
      await tracker.cleanup();
      for (const item of [...storage, healthy]) item.cleanup();
    }
  });

  it("does not forget allocations made while cleanup yields", async () => {
    const tracker = createTempDatabaseTracker();
    const first = tracker.makePath("first");
    try {
      const cleanup = tracker.cleanup();
      const second = tracker.makePath("second");
      await cleanup;
      expect(existsSync(dirname(first))).toBe(false);
      expect(existsSync(dirname(second))).toBe(true);
      await tracker.cleanup();
      expect(existsSync(dirname(second))).toBe(false);
    } finally { await tracker.cleanup(); }
  });

  for (const code of ["EBUSY", "EPERM"]) {
    it(`retries transient ${code} removal at most twice before succeeding`, async () => {
      let attempts = 0;
      const storage = createOwnedTestDirectory("memory-json-retry-", {
        remove(path) {
          if (++attempts < 3) throw Object.assign(new Error("temporarily busy"), { code });
          rmSync(path, { recursive: true, force: false });
        },
      });
      const tracker = createTempDatabaseTracker(() => storage);
      tracker.makePath("helper");
      try {
        await tracker.cleanup();
        expect(attempts).toBe(3);
        expect(existsSync(storage.dir)).toBe(false);
      } finally { attempts = 3; storage.cleanup(); }
    });
  }

  it("bounds persistent busy retries and retains the directory for later recovery", async () => {
    let attempts = 0, busy = true;
    const failure = Object.assign(new Error("still locked"), { code: "EBUSY" });
    const storage = createOwnedTestDirectory("memory-json-persistent-", {
      remove(path) {
        attempts++;
        if (busy) throw failure;
        rmSync(path, { recursive: true, force: false });
      },
    });
    const tracker = createTempDatabaseTracker(() => storage);
    tracker.makePath("helper");
    try {
      await expect(tracker.cleanup()).rejects.toThrow(storage.dir);
      expect(attempts).toBe(3);
      expect(existsSync(storage.dir)).toBe(true);
      busy = false;
      await tracker.cleanup();
      expect(attempts).toBe(4);
      expect(existsSync(storage.dir)).toBe(false);
    } finally { busy = false; storage.cleanup(); }
  });

  for (const failure of ["non-error", new Error("ownership changed"),
    new Error("invalid cause", { cause: "EBUSY" }),
    new Error("denied", { cause: Object.assign(new Error("denied"), { code: "EACCES" }) })]) {
    it(`does not retry a failure without a recognized busy removal cause: ${String(failure)}`, async () => {
      const storage = createOwnedTestDirectory("memory-json-no-retry-");
      let attempts = 0;
      const tracker = createTempDatabaseTracker(() => ({ ...storage, cleanup() { attempts++; throw failure; } }));
      tracker.makePath("helper");
      try {
        await expect(tracker.cleanup()).rejects.toThrow(storage.dir);
        expect(attempts).toBe(1);
        expect(existsSync(storage.dir)).toBe(true);
      } finally { storage.cleanup(); }
    });
  }

  it("revalidates directory identity before a delayed retry", async () => {
    let attempts = 0;
    const storage = createOwnedTestDirectory("memory-json-retry-identity-", {
      remove(path) {
        if (++attempts === 1) {
          renameSync(path, path + "-original");
          mkdirSync(path);
          writeFileSync(join(path, "foreign.txt"), "replacement must survive");
          throw Object.assign(new Error("busy after replacement"), { code: "EBUSY" });
        }
        rmSync(path, { recursive: true, force: false });
      },
    });
    const tracker = createTempDatabaseTracker(() => storage);
    tracker.makePath("helper");
    const sentinel = join(storage.dir, "foreign.txt");
    try {
      await expect(tracker.cleanup()).rejects.toThrow(storage.dir);
      expect(attempts).toBe(1);
      expect(readFileSync(sentinel, "utf8")).toBe("replacement must survive");
    } finally {
      unlinkSync(sentinel);
      rmdirSync(storage.dir);
      renameSync(storage.dir + "-original", storage.dir);
      await tracker.cleanup();
    }
    expect(attempts).toBe(2);
    expect(existsSync(storage.dir)).toBe(false);
  });
});

