/**
 * search.json.test.ts
 *
 * CLI-02 envelope assertions for search command (Plan 32-02).
 *
 * Asserts that --json output on EVERY exit path emits a QueryResultEnvelope
 * (success/empty) or QueryErrorEnvelope (validation/catch). Per Codex HIGH-2,
 * not just the catch block.
 *
 * Includes:
 *   - describe("--files --json")  Codex HIGH-4: envelope on file-search branch
 *   - describe("--json --format ai routing")  Codex HIGH-5: deep-equal payload
 *
 * Error-path strategy (Codex HIGH-3 resolution):
 *   Strategy A — deterministic invalid input (empty query / negative limit /
 *   invalid date). NO mock.module() on first-party (isolation gate).
 *   NO dbPath: "/non/existent/..." (Windows file-locking non-deterministic).
 */

import { describe, expect, it, afterEach } from "bun:test";
import { executeSearchCommand } from "file:///C:/Projects/memory-nexus/src/presentation/cli/commands/search.ts";
import {
  captureStreams,
  createTempDatabaseTracker,
} from "./tests/helpers/capture-json.js";

describe("search --json envelope (Plan 32-02 CLI-02)", () => {
  const tempDatabase = createTempDatabaseTracker();

  afterEach(() => {
    return tempDatabase.cleanup();
  });

  describe("A. valid JSON on success path (empty DB → empty results)", () => {
    it("emits envelope with schema_version, command, kind, data", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout, exitCode } = await captureStreams(() =>
        executeSearchCommand("query", { json: true, dbPath })
      );
      expect(exitCode).toBe(0);
      const parsed = JSON.parse(stdout);
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("search");
      expect(parsed.kind).toBe("message");
      expect(parsed.data).toBeDefined();
      expect(parsed.error).toBeUndefined();
    });
  });

  describe("B. envelope on EMPTY result", () => {
    it("emits envelope with data: [] not plain text", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout, exitCode } = await captureStreams(() =>
        executeSearchCommand("definitely-no-results-zxqv-12345", {
          json: true,
          dbPath,
        })
      );
      expect(exitCode).toBe(0);
      const parsed = JSON.parse(stdout);
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("search");
      expect(Array.isArray(parsed.data)).toBe(true);
      expect(parsed.data.length).toBe(0);
      expect(parsed.error).toBeUndefined();
    });
  });

  describe("C. envelope on VALIDATION error", () => {
    it("emits error envelope on empty query", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout, exitCode } = await captureStreams(() =>
        executeSearchCommand("", { json: true, dbPath })
      );
      expect(exitCode).toBe(1);
      const parsed = JSON.parse(stdout);
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("search");
      expect(parsed.error).toBeDefined();
      expect(typeof parsed.error.code).toBe("string");
      expect(typeof parsed.error.message).toBe("string");
      expect(parsed.data).toBeUndefined();
    });

    it("emits error envelope on invalid limit", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout, exitCode } = await captureStreams(() =>
        executeSearchCommand("q", { json: true, dbPath, limit: "-1" })
      );
      expect(exitCode).toBe(1);
      const parsed = JSON.parse(stdout);
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("search");
      expect(parsed.error).toBeDefined();
    });

    it("emits error envelope on invalid since-date", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout, exitCode } = await captureStreams(() =>
        executeSearchCommand("q", {
          json: true,
          dbPath,
          since: "garbage-date-zzz",
        })
      );
      expect(exitCode).toBe(1);
      const parsed = JSON.parse(stdout);
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("search");
      expect(parsed.error).toBeDefined();
    });
  });

  describe("F. stdout is EXACTLY ONE JSON document in --json mode", () => {
    it("emits parseable JSON without preceding/trailing non-JSON lines", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout } = await captureStreams(() =>
        executeSearchCommand("query", { json: true, dbPath })
      );
      // Should not throw — single JSON document.
      expect(() => JSON.parse(stdout)).not.toThrow();
      // No content before the first `{` or after the final `}`.
      const trimmed = stdout.trim();
      expect(trimmed.startsWith("{")).toBe(true);
      expect(trimmed.endsWith("}")).toBe(true);
    });
  });

  describe("H. per-command meta assertion", () => {
    it("includes meta.query and meta.mode for empty search", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout } = await captureStreams(() =>
        executeSearchCommand("specific-query-for-meta", {
          json: true,
          dbPath,
        })
      );
      const parsed = JSON.parse(stdout);
      expect(parsed.meta).toBeDefined();
      expect(parsed.meta.query).toBe("specific-query-for-meta");
    });
  });

  describe("I. --files --json (Codex HIGH-4)", () => {
    it("emits envelope with kind: 'file' regardless of qmd availability", async () => {
      const dbPath = tempDatabase.makePath("search");
      const { stdout, exitCode } = await captureStreams(() =>
        executeSearchCommand("foo", { json: true, files: true, dbPath })
      );
      // Parse the captured stdout as JSON — must succeed.
      const parsed = JSON.parse(stdout);
      // The envelope shape is the SAME contract as the DB path.
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("search");
      if (exitCode === 0) {
        // qmd available: kind is "file", data is an array.
        expect(parsed.kind).toBe("file");
        expect(Array.isArray(parsed.data)).toBe(true);
      } else {
        // qmd unavailable: error envelope with code referring to qmd-unavailable.
        expect(parsed.error).toBeDefined();
        expect(typeof parsed.error.code).toBe("string");
      }
    });
  });

  describe("J. --json --format ai routing equivalence (Codex HIGH-5)", () => {
    it("deep-equals --json alone vs --json --format ai (search)", async () => {
      const dbPath = tempDatabase.makePath("search");
      // Run with --json alone
      const { stdout: stdoutA } = await captureStreams(() =>
        executeSearchCommand("equivalence-test", { json: true, dbPath })
      );
      // Run with --json --format ai (same DB, fresh capture)
      const { stdout: stdoutB } = await captureStreams(() =>
        executeSearchCommand("equivalence-test", {
          json: true,
          format: "ai",
          dbPath,
        })
      );
      // Strip meta.timing_ms before comparison (non-deterministic).
      const stripTiming = (s: string): unknown => {
        const obj = JSON.parse(s);
        if (obj.meta && "timing_ms" in obj.meta) delete obj.meta.timing_ms;
        return obj;
      };
      expect(stripTiming(stdoutA)).toEqual(stripTiming(stdoutB));
    });
  });
});

/**
 * context.json.test.ts
 *
 * CLI-02 envelope assertions for context command (Plan 32-02).
 *
 * Asserts envelope shape on every exit path. The KEY test is HIGH-5
 * (--json --format ai routing equivalence): context.ts:118 has a
 * routing fork (SmartContextService vs Legacy), and --json must take
 * the SAME path regardless of --format ai.
 *
 * Error-path strategy: Strategy A (project-not-found → empty result).
 */

import { describe, expect, it, afterEach } from "bun:test";
import { executeContextCommand } from "file:///C:/Projects/memory-nexus/src/presentation/cli/commands/context.ts";
import {
  captureStreams,
  createTempDatabaseTracker,
} from "./tests/helpers/capture-json.js";

describe("context --json envelope (Plan 32-02 CLI-02)", () => {
  const tempDatabase = createTempDatabaseTracker();

  afterEach(() => {
    return tempDatabase.cleanup();
  });

  describe("D. envelope on NOT-FOUND (empty DB → project missing)", () => {
    it("emits envelope (or error envelope) — not bespoke shape", async () => {
      const dbPath = tempDatabase.makePath("context");
      const { stdout } = await captureStreams(() =>
        executeContextCommand("nonexistent-project-zzz", {
          json: true,
          dbPath,
        })
      );
      const parsed = JSON.parse(stdout);
      // Envelope shape: schema_version + command + (data or error)
      expect(parsed.schema_version).toBe("1");
      expect(parsed.command).toBe("context");
      // Either data: <something> OR error: {...} but not legacy "results"
      const hasData = parsed.data !== undefined;
      const hasError = parsed.error !== undefined;
      expect(hasData || hasError).toBe(true);
    });
  });

  describe("F. stdout is exactly one JSON document", () => {
    it("parses cleanly", async () => {
      const dbPath = tempDatabase.makePath("context");
      const { stdout } = await captureStreams(() =>
        executeContextCommand("project-name", { json: true, dbPath })
      );
      expect(() => JSON.parse(stdout)).not.toThrow();
      const trimmed = stdout.trim();
      expect(trimmed.startsWith("{")).toBe(true);
      expect(trimmed.endsWith("}")).toBe(true);
    });
  });

  describe("H. meta.project echoes input", () => {
    it("includes project in meta", async () => {
      const dbPath = tempDatabase.makePath("context");
      const { stdout } = await captureStreams(() =>
        executeContextCommand("my-project-name", { json: true, dbPath })
      );
      const parsed = JSON.parse(stdout);
      // meta may live on success OR be omitted on error; assertion is loose.
      if (parsed.meta) {
        expect(parsed.meta.project).toBe("my-project-name");
      }
    });
  });

  describe("J. --json --format ai routing equivalence (Codex HIGH-5 — canonical)", () => {
    it("deep-equals --json alone vs --json --format ai", async () => {
      const dbPath = tempDatabase.makePath("context");
      // Run with --json alone (routing decision depends on budget/cross-project only)
      const { stdout: stdoutA } = await captureStreams(() =>
        executeContextCommand("equivalence-test", {
          json: true,
          dbPath,
        })
      );
      // Run with --json --format ai (must take SAME path — HIGH-5)
      const { stdout: stdoutB } = await captureStreams(() =>
        executeContextCommand("equivalence-test", {
          json: true,
          format: "ai",
          dbPath,
        })
      );
      // Both must be parseable JSON
      const parsedA = JSON.parse(stdoutA);
      const parsedB = JSON.parse(stdoutB);
      // Deep-equal (not just both-parseable per HIGH-5)
      expect(parsedA).toEqual(parsedB);
    });

    it("deep-equals --json --budget vs --json --budget --format ai", async () => {
      const dbPath = tempDatabase.makePath("context");
      // --budget triggers SmartContextService routing
      const { stdout: stdoutA } = await captureStreams(() =>
        executeContextCommand("budget-test", {
          json: true,
          budget: 1000,
          dbPath,
        })
      );
      const { stdout: stdoutB } = await captureStreams(() =>
        executeContextCommand("budget-test", {
          json: true,
          budget: 1000,
          format: "ai",
          dbPath,
        })
      );
      const parsedA = JSON.parse(stdoutA);
      const parsedB = JSON.parse(stdoutB);
      expect(parsedA).toEqual(parsedB);
    });
  });
});

/**
 * show.json.test.ts
 *
 * CLI-02 envelope assertions for show command (Plan 32-02).
 *
 * Asserts envelope shape on success + not-found + catch paths.
 *
 * Error-path strategy: Strategy A — nonexistent session ID for not-found.
 *   NO mock.module() on first-party (isolation gate).
