import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-json-callers-');
const commands=['search','context','show','list','related','stats'];
const paths=commands.map(command=>`src/presentation/cli/commands/${command}.json.test.ts`);
const inputs:unknown[]=[];
try {
 mkdirSync(join(storage.dir,'tests/helpers'),{recursive:true});
 for(const file of ['capture-json.ts','owned-test-directory.ts'])writeFileSync(join(storage.dir,'tests/helpers',file),readFileSync(join(root,'tests/helpers',file)));
 for(const [index,path] of paths.entries()){
  const command=commands[index]!,source=readFileSync(path,'utf8');
  const originalCommand=`"./${command}.js"`,originalHelper='"../../../../tests/helpers/capture-json.js"';
  if(source.split(originalCommand).length!==2||source.split(originalHelper).length!==2)throw Error('Import relocation seam changed');
  const relocated=source.replace(originalCommand,JSON.stringify(pathToFileURL(join(root,`src/presentation/cli/commands/${command}.ts`)).href)).replace(originalHelper,'"./tests/helpers/capture-json.js"');
  const instrumented=instrumentTypeScriptWithCoverage(relocated,resolve(path));
  writeFileSync(join(storage.dir,`${command}.json.test.ts`),instrumented.code);
  inputs.push({path,sourceHash:sourceHash(source),relocatedHash:sourceHash(relocated),relocatedSource:relocated});
 }
 writeFileSync(join(storage.dir,'capture.ts'),'import {afterAll} from "bun:test"; import {writeFileSync} from "node:fs"; afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 writeFileSync(join(storage.dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+', "./capture.ts"]\n');
 const run=Bun.spawnSync([process.execPath,'test','--timeout','15000',...commands.map(command=>`${command}.json.test.ts`)],{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
 const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
 writeFileSync('.git/b11-json-callers-run.txt',output);
 if(run.exitCode!==0)throw Error('Instrumented callers failed; see retained output');
 const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
 const files=paths.map(path=>{
  const measured=map.fileCoverageFor(resolve(path)),data=measured.data;
  return {path,sourceHash:sourceHash(readFileSync(path,'utf8')),metrics:measured.toSummary().data,
   uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index],type:data.branchMap[id]?.type}]:[])),
   uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};
 });
 writeFileSync('.git/b11-json-callers-measure.json',JSON.stringify({scope:'Diagnostic only. Imports relocated to original production source and copied owned helper; bodies unchanged. No B05 completeness, native Linux or final quality acceptance.',recordedAt:new Date().toISOString(),runtime:Bun.version,exit:run.exitCode,files,inputs,rawCoverage:raw,output,probeSource:readFileSync('.git/b11-json-callers-measure.ts','utf8')},null,2)+'\n');
 console.log(JSON.stringify(files));
}finally{storage.cleanup();}

