import {readFileSync,lstatSync,realpathSync,rmSync,existsSync,writeFileSync} from 'node:fs';
import {join,dirname} from 'node:path';
import {tmpdir} from 'node:os';
const log=readFileSync('.git/b11-json-retry-red.txt','utf8');
const names=[...new Set(log.match(/memory-json-retry-[A-Za-z0-9]+/g))];
if(names.length!==2)throw Error('Unexpected retained fixture inventory');
const parent=realpathSync(tmpdir()),records:unknown[]=[];
for(const name of names){
 const path=join(parent,name),stat=lstatSync(path,{bigint:true}),marker=join(path,'.memory-test-owner.json');
 const markerStat=lstatSync(marker),owner=JSON.parse(readFileSync(marker,'utf8'));
 if(dirname(path)!==parent||realpathSync(path)!==path||!stat.isDirectory()||stat.isSymbolicLink()||!markerStat.isFile()||markerStat.isSymbolicLink()||markerStat.nlink!==1||owner.project!=='memory-nexus'||owner.dir!==path||owner.device!==stat.dev.toString()||owner.inode!==stat.ino.toString())throw Error('Ownership mismatch');
 let live=true;try{process.kill(owner.pid,0);}catch(error){if((error as NodeJS.ErrnoException).code==='ESRCH')live=false;else throw error;}
 if(live)throw Error('Fixture owner still active');
 rmSync(path,{recursive:true,force:false});
 records.push({path,owner,removed:!existsSync(path),basis:'Exact path named by terminal RED run, regular single-link marker, matching canonical directory/device/inode and terminated owner PID.'});
}
writeFileSync('.git/b11-json-red-fixture-recovery.json',JSON.stringify({recordedAt:new Date().toISOString(),records,source:readFileSync('.git/b11-json-red-fixture-recovery.ts','utf8')},null,2)+'\n');
console.log(JSON.stringify(records));

