import {Database} from 'bun:sqlite';
import {writeFileSync,rmSync,existsSync} from 'node:fs';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const results:unknown[]=[];
for(const mode of ['default','strict','finalize-first'] as const){
 const storage=createOwnedTestDirectory('memory-json-close-'),path=join(storage.dir,'probe.db');
 const db=new Database(path);db.exec('CREATE TABLE sample (value INTEGER); INSERT INTO sample VALUES (1);');
 const statement=db.prepare('SELECT value FROM sample');statement.get();
 let closeError:string|null=null,queryAfterClose:unknown,removalError:string|null=null;
 try{
  if(mode==='finalize-first')statement.finalize();
  try{db.close(mode==='strict');}catch(error){closeError=String(error);}
  try{queryAfterClose=statement.get();}catch(error){queryAfterClose=String(error);}
  try{rmSync(path,{force:false});}catch(error){removalError=String(error);}
  results.push({mode,closeError,queryAfterClose,removalError,removed:!existsSync(path)});
 }finally{statement.finalize();db.close();storage.cleanup();}
}
writeFileSync('.git/b11-json-close-probe.json',JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,platform:process.platform,results,source:readFileSyncSelf()},null,2)+'\n');
console.log(JSON.stringify(results));
function readFileSyncSelf(){return require('node:fs').readFileSync('.git/b11-json-close-probe.ts','utf8');}

